package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="auditoria") public class AuditoriaEvento {
 @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false,updatable=false) private UUID empresaId; @Column(name="usuario_id",updatable=false) private UUID usuarioId; @Column(nullable=false,updatable=false) private LocalDateTime fecha=LocalDateTime.now(); @Column(nullable=false,updatable=false) private String modulo; @Column(nullable=false,updatable=false) private String accion; @Column(updatable=false) private String entidad; @Column(name="registro_id",updatable=false) private UUID registroId; @Column(updatable=false) private String recurso; @Column(name="paciente_id",updatable=false) private UUID pacienteId; @Column(name="rol_usuario",updatable=false) private String rolUsuario; @Column(updatable=false) private String ip; @Column(updatable=false) private String dispositivo; @Column(name="datos_anteriores",updatable=false) private String datosAnteriores; @Column(name="datos_nuevos",updatable=false) private String datosNuevos; @Column(nullable=false,updatable=false) private String resultado="SUCCESS"; @Column(updatable=false) private String motivo; @Column(nullable=false,updatable=false) private boolean sensible;
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public UUID getUsuarioId(){return usuarioId;} public void setUsuarioId(UUID v){usuarioId=v;} public LocalDateTime getFecha(){return fecha;} public void setFecha(LocalDateTime v){fecha=v;} public String getModulo(){return modulo;} public void setModulo(String v){modulo=v;} public String getAccion(){return accion;} public void setAccion(String v){accion=v;} public String getEntidad(){return entidad;} public void setEntidad(String v){entidad=v;} public UUID getRegistroId(){return registroId;} public void setRegistroId(UUID v){registroId=v;} public String getRecurso(){return recurso;} public void setRecurso(String v){recurso=v;} public UUID getPacienteId(){return pacienteId;} public void setPacienteId(UUID v){pacienteId=v;} public String getRolUsuario(){return rolUsuario;} public void setRolUsuario(String v){rolUsuario=v;} public String getIp(){return ip;} public void setIp(String v){ip=v;} public String getDispositivo(){return dispositivo;} public void setDispositivo(String v){dispositivo=v;} public String getDatosAnteriores(){return datosAnteriores;} public void setDatosAnteriores(String v){datosAnteriores=v;} public String getDatosNuevos(){return datosNuevos;} public void setDatosNuevos(String v){datosNuevos=v;} public String getResultado(){return resultado;} public void setResultado(String v){resultado=v;} public String getMotivo(){return motivo;} public void setMotivo(String v){motivo=v;} public boolean isSensible(){return sensible;} public void setSensible(boolean v){sensible=v;}
}
